public class BusinessHoursRequirement : IAuthorizationRequirement
{
    public TimeSpan StartTime { get; }
    public TimeSpan EndTime { get; }
    public bool AllowWeekends { get; }

    public BusinessHoursRequirement(
        TimeSpan startTime, 
        TimeSpan endTime, 
        bool allowWeekends = false)
    {
        StartTime = startTime;
        EndTime = endTime;
        AllowWeekends = allowWeekends;
    }
}

public class BusinessHoursHandler : 
    AuthorizationHandler<BusinessHoursRequirement>
{
    protected override Task HandleRequirementAsync(
        AuthorizationHandlerContext context,
        BusinessHoursRequirement requirement)
    {
        var now = DateTime.UtcNow.TimeOfDay;
        var day = DateTime.UtcNow.DayOfWeek;

        // Check time
        if (now < requirement.StartTime || now > requirement.EndTime)
        {
            return Task.CompletedTask;
        }

        // Check weekend
        if (!requirement.AllowWeekends && 
            (day == DayOfWeek.Saturday || day == DayOfWeek.Sunday))
        {
            return Task.CompletedTask;
        }

        context.Succeed(requirement);
        return Task.CompletedTask;
    }
}

