public class SubscriptionTierRequirement : IAuthorizationRequirement
{
    public string MinimumTier { get; }
    public SubscriptionTierRequirement(string minimumTier) => MinimumTier = minimumTier;
}

public class LicenseValidityRequirement : IAuthorizationRequirement { }

// Handlers
public class SubscriptionHandler : 
    AuthorizationHandler<SubscriptionTierRequirement>
{
    private readonly ISubscriptionService _subscriptionService;

    public SubscriptionHandler(ISubscriptionService subscriptionService)
    {
        _subscriptionService = subscriptionService;
    }

    protected override async Task HandleRequirementAsync(
        AuthorizationHandlerContext context,
        SubscriptionTierRequirement requirement)
    {
        var userId = context.User.FindFirst(ClaimTypes.NameIdentifier)?.Value;
        if (string.IsNullOrEmpty(userId)) return;

        var tier = await _subscriptionService.GetUserTierAsync(userId);
        if (IsTierSufficient(tier, requirement.MinimumTier))
        {
            context.Succeed(requirement);
        }
    }

    private bool IsTierSufficient(string current, string minimum)
    {
        var tiers = new[] { "Free", "Pro", "Enterprise" };
        return tiers.ToList().IndexOf(current) >= tiers.ToList().IndexOf(minimum);
    }
}

public class LicenseHandler : 
    AuthorizationHandler<LicenseValidityRequirement>
{
    private readonly ILicenseService _licenseService;

    public LicenseHandler(ILicenseService licenseService)
    {
        _licenseService = licenseService;
    }

    protected override async Task HandleRequirementAsync(
        AuthorizationHandlerContext context,
        LicenseValidityRequirement requirement)
    {
        var orgId = context.User.FindFirst("OrganizationId")?.Value;
        if (string.IsNullOrEmpty(orgId)) return;

        var isValid = await _licenseService.IsLicenseValidAsync(orgId);
        if (isValid)
        {
            context.Succeed(requirement);
        }
    }
}

