import { useAuth } from './useAuth';

type Permission = 'document:read' | 'document:write' | 'report:export';

function useHasPermission(requiredPermission: Permission): boolean {
  const { user } = useAuth();

  if (!user?.permissions) return false;

  // Supports wildcard: 'report:*' covers 'report:export'
  const hasExact = user.permissions.includes(requiredPermission);
  const [resource] = requiredPermission.split(':');
  const hasWildcard = user.permissions.includes(`${resource}:*`);

  return hasExact || hasWildcard;
}

function DocumentActions({ documentId }: { documentId: string }) {
  const canWrite = useHasPermission('document:write');
  const canDelete = useHasPermission('document:delete');

  return (
    <div className="flex gap-2">
      <button onClick={() => editDocument(documentId)} disabled={!canWrite}>
        Edit
      </button>
      <button onClick={() => deleteDocument(documentId)} disabled={!canDelete} className="text-red-600">
        Delete
      </button>
    </div>
  );
}
